import io
import sys
from unittest.mock import patch
from rich.console import Console
from rich.live import Live

class MockStdout(io.TextIOBase):
    def __init__(self):
        self._isatty = True
        self._fileno = 1
        self._closed = False
        self._encoding = 'utf-8'
        self._name = '<mock_stdout>'
        self._mode = 'w'

    def isatty(self):
        return self._isatty

    def fileno(self):
        return self._fileno

    def write(self, s):
        # Simulate writing, but don't actually write to real stdout
        return len(s)

    def flush(self):
        pass

    @property
    def closed(self):
        return self._closed

    @property
    def encoding(self):
        return self._encoding

    @property
    def name(self):
        return self._name

    @property
    def mode(self):
        return self._mode

    # Add other methods that might be called by TextIOBase or FileProxy
    def readable(self): return False
    def writable(self): return True
    def seekable(self): return False
    def read(self, size=-1): return ''
    def readline(self, size=-1): return ''
    def tell(self): return 0
    def seek(self, offset, whence=0): return 0
    def close(self): self._closed = True

def test_fileproxy_isatty_delegation():
    console = Console()

    mock_stdout_instance = MockStdout()

    with patch('sys.stdout', new=mock_stdout_instance):
        with Live(\"hello\", console=console, redirect_stdout=True):
            # This assertion should FAIL because FileProxy.isatty() (inherited from io.TextIOBase)
            # will return False, even though our underlying mock_stdout_instance.isatty() returns True.
            assert sys.stdout.isatty() is True
